        if (c == '"') in_quote = !in_quote;
        if (!in_quote && c == '#') break;
        out += c;
    }
    return out;
}

// Remove surrounding double quotes if present.
std::string unquote(const std::string& s) {
    if (s.size() >= 2 && s.front() == '"' && s.back() == '"')
        return s.substr(1, s.size() - 2);
    return s;
}

