    size_t close = line.find(']');
    if (close == std::string::npos) continue;
    if (close + 2 > line.size() || line[close + 1] != ' ') continue;

    std::string timestamp = line.substr(1, close - 1);
    size_t levelStart = close + 2;
    size_t colon = line.find(':', levelStart);
    if (colon == std::string::npos) continue;
    std::string level = line.substr(levelStart, colon - levelStart);
    if (colon + 2 > line.size() || line[colon + 1] != ' ') continue;
    std::string message = line.substr(colon + 2);

    LogEntry e;
    e.timestamp = timestamp;
    e.level = level;
    e.message = message;
    result.push_back(e);
}
return result;

