// - Lines starting with # are comments (ignored).
// - A line ending with backslash continues onto the next line;
//   the backslash is removed and the next line's leading spaces are trimmed,
//   then joined directly (no extra space).
// - Blank lines are ignored.
static std::string ltrim(const std::string& s) {
    size_t i = 0; while (i < s.size() && s[i] == ' ') i++;
    return s.substr(i);
}
static std::string rtrim(const std::string& s) {
    size_t i = s.size(); while (i > 0 && s[i-1] == ' ') i--;
    return s.substr(0, i);
}
std::map<std::string, std::string> parseMakefile(const std::string& text) {
    std::map<std::string, std::string> vars;
    std::istringstream stream(text);
    std::string raw, pending;
    while (std::getline(stream, raw)) {
        if (!pending.empty()) raw = ltrim(raw);
        if (!raw.empty() && raw.back() == '\\') { pending += raw.substr(0, raw.size()-1); continue; }
