// Parse YAML-like key-value text into a flat map with dotted keys.
// - "key: value" where indent (2 spaces per level) determines nesting.
// - "key:" with no value is a section header; children get "section." prefix.
// - # comments (after optional spaces) and blank lines ignored.
// - Quoted values ("...") strip quotes; # inside quotes is NOT a comment.
// - Unquoted values trimmed, # starts inline comment.
std::map<std::string, std::string> parseYaml(const std::string& text) {
    std::map<std::string, std::string> result;
    std::vector<std::string> stack;
    std::istringstream stream(text);
    std::string line;
    while (std::getline(stream, line)) {
        size_t indent = 0; while (indent < line.size() && line[indent] == ' ') indent++;
        std::string tr = line.substr(indent);
        if (tr.empty() || tr[0] == '#') continue;
        int level = indent / 2;
        if ((int)stack.size() > level) stack.resize(level);
        size_t colon = tr.find(':'); if (colon == std::string::npos) continue;
        std::string key = tr.substr(0, colon);
        std::string rest = tr.substr(colon + 1);
        size_t rs = 0; while (rs < rest.size() && rest[rs] == ' ') rs++; rest = rest.substr(rs);

golden_completion:
