    if (rest[0] == '"') { size_t end = rest.find('"', 1); val = (end != std::string::npos) ? rest.substr(1, end-1) : rest.substr(1); }
    else { size_t c = rest.find('#'); val = rest.substr(0, c); while (!val.empty() && val.back()==' ') val.pop_back(); }
    std::string fk; for (auto& s : stack) fk += s + "."; fk += key;
    result[fk] = val;
}
