    for (size_t i = 0; i < n; ++i) {
        double r = rng.next() * total;
        double cum = 0.0;
        for (size_t j = 0; j < items.size(); ++j) {
            cum += weights[j];
            if (r < cum) {
                result.push_back(items[j]);
                break;
            }
        }
        if (result.size() <= i) {
            result.push_back(items.back());
        }
    }
    return result;
}
